INSERT INTO "live_sessions" ("id", "mapel", "kode", "durasi_detik", "judul", "admin_id", "created_at", "questions", "current_started_at", "current_index", "status") VALUES ('xHTTFy345rjtRCkAXyb3', 'Fisika', 'EV8SPE', '120', 'Latihan SOAL materi Gaya', 'loYyLXkg7qta0czE0WnM', '{"_seconds":1788783929,"_nanoseconds":505076000}', '[{"jawaban_benar":"B","pilihan":["2 m/s²","4 m/s²","6 m/s²","8 m/s²"],"penjelasan":"","id":"q1_1788784337_0","pertanyaan":"Sebuah benda bermassa 6 kg didorong dengan gaya 24 N. Berapa percepatan yang dialami benda tersebut?"},{"jawaban_benar":"C","pilihan":["4 kg","6 kg","8 kg","10 kg"],"penjelasan":"","id":"q2_1788784337_1","pertanyaan":"Sebuah benda mengalami percepatan 5 m/s² akibat gaya sebesar 40 N. Berapa massa benda tersebut?"},{"jawaban_benar":"C","pilihan":["3 N","13 N","30 N","300 N"],"penjelasan":"","id":"q3_1788784337_2","pertanyaan":"Sebuah balok bermassa 3 kg berada di permukaan bumi (g = 10 m/s²). Berapa besar gaya berat balok tersebut?"},{"jawaban_benar":"C","pilihan":["3 m/s²","4 m/s²","5 m/s²","6,25 m/s²"],"penjelasan":"","id":"q4_1788784337_3","pertanyaan":"Sebuah kotak bermassa 8 kg ditarik dengan gaya 50 N ke kanan, namun terdapat gaya gesek 10 N yang melawan arah gerak. Berapa percepatan kotak tersebut?"},{"jawaban_benar":"B","pilihan":["2 m/s²","4 m/s²","6 m/s²","8 m/s²"],"penjelasan":"","id":"q5_1788784337_4","pertanyaan":"Dua gaya bekerja pada sebuah benda bermassa 10 kg: gaya pertama 60 N ke kanan dan gaya kedua 20 N ke kiri. Berapa percepatan benda tersebut?"},{"jawaban_benar":"C","pilihan":["4 m/s²","5 m/s²","6 m/s²","7,5 m/s²"],"penjelasan":"","id":"q6_1788784337_5","pertanyaan":"Sebuah mobil mainan bermassa 1,5 kg diberi gaya dorong sebesar 9 N. Berapa percepatan mobil mainan tersebut?"},{"jawaban_benar":"C","pilihan":["24 N","36 N","48 N","72 N"],"penjelasan":"","id":"q7_1788784337_6","pertanyaan":"Sebuah balok bermassa 4 kg bergerak melingkar dengan kecepatan 6 m/s pada lintasan berjari-jari 3 m. Berapa besar ga